context_info = ()
for d in context:
    q = "You are given one document. Extract only information contained in this document; do not use outside knowledge. Then test whether it can contribute to solving the following puzzle. Provide clear dates with year-month-day where possible and include quotes.\n\nPuzzle constraints:\n- A film critic, who reviewed movies for over 40 years until their death, published a review of a 1990s film 14 days after its premiere.\n- The critic died 14 years, 9 months, and 16 days after that review was published (end date excluded).\n- One of the movie's writers died 21 years, 6 months, and 14 days after the film's premiere (end date excluded).\n- We need the title of this writer's first published book.\n\nFor THIS document only, do the following:\n1) Identify any 1990s film(s) mentioned. For each, list:\n   - Title\n   - Premiere date(s) (normalize to YYYY-MM-DD if possible) and location if given\n   - Release date(s)\n   - Credited writer(s) and any birth/death dates included in the doc\n   - Any mention of a writer’s first published book (title and year), if present\n   Provide quotes for each item.\n2) Identify any film critic(s) mentioned. For each, list:\n   - Name\n   - Whether the doc states they reviewed movies for over 40 years until their death\n   - Death date (YYYY-MM-DD if given)\n   - Any review publication dates tied to the 1990s film(s)\n   Provide quotes.\n3) Identify any explicit review(s) in the doc. For each, list:\n   - Critic name\n   - Film reviewed\n   - Review publication date (YYYY-MM-DD)\n   Provide quotes.\n4) If the document alone provides enough data to test the puzzle constraints for a candidate film/critic/writer, do the date arithmetic using the exact dates given here (exclude the end date when computing the time differences). Show working. State whether the constraints are satisfied.\n5) Even if not enough, summarize the potentially relevant items from this doc for the puzzle.\n"
    result = llm_query("BEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT\n" + q)
    context_info = context_info + (result,)

aggregated = "\n\n-----\n\n".join(context_info)

final_prompt = "You are given extracted notes from multiple documents. Use ONLY this material. Solve the puzzle by identifying the specific film, critic, and writer that satisfy all constraints. Then provide ONLY the title of that writer's first published book as the final output.\n\nImportant:\n- Base everything solely on the provided notes; do not use outside knowledge.\n- Normalize dates. When computing the intervals, exclude the end date.\n- Verify all three constraints simultaneously:\n  1) A film critic, who reviewed movies for over 40 years until their death, published a review of a 1990s film exactly 14 days after the film's premiere.\n  2) The critic died exactly 14 years, 9 months, and 16 days after the review publication date (end date excluded).\n  3) One of that film’s writers died exactly 21 years, 6 months, and 14 days after the film's premiere (end date excluded).\n- After validating, identify that writer and report the title of their first published book.\n- Output format: ONLY the title of the first published book. No quotes. No extra words.\n\nHere are the notes from the documents:\n\n" + aggregated + "\n\nNow, determine the correct answer and output only the book title."

result = llm_query(final_prompt)
return_result(result)